// Recorded sound effects (Kenney CC0 kits, chimes from FluidR3), arena music with an action layer,
// and the original synthesized cues as a fallback while samples load or if they cannot decode.
const CUES={seat:[290,180,.055,.012],rustle:[115,75,.1,.006],castAir:[460,990,.22,.021],castFire:[180,75,.20,.025],castNature:[115,230,.24,.027],castWater:[680,290,.25,.021],select:[420,510,.07,.018],pair:[520,780,.18,.030],place:[240,410,.12,.035],repair:[310,620,.18,.03],deliver:[380,570,.16,.025],wrong:[180,145,.14,.018],coin:[880,1175,.12,.018],impact:[105,55,.16,.045],jump:[220,340,.14,.018],land:[95,48,.13,.03],reward:[523,1046,.38,.035],step:[130,70,.065,.012],correct:[660,990,.14,.025],coinTick:[1320,1560,.05,.01],chest:[523,1568,.5,.035],quest:[784,1175,.3,.03],hurt:[300,120,.2,.03],defeat:[200,60,.4,.04],break:[900,200,.25,.03]};
// Sample cues mapped from game events; volumes keep effects balanced against the music.
const VOLUME={seat:.22,step:.32,land:.5,jump:.45,coin:.55,coinTick:.35,impact:.7,hurt:.6,defeat:.6,break:.7,place:.55,repair:.5,deliver:.55,select:.4,correct:.6,pair:.55,wrong:.45,reward:.6,chest:.75,quest:.6};
const GAP={step:.16,coinTick:.03};
export class GameAudio{
 constructor({sfx='assets/sfx/',music='assets/music/'}={}){this.context=null;this.wind=null;this.voices=0;this.last=new Map();this.lastPosition=null;this.distance=0;this.stage='ground';this.reading=false;this.muted=false;this.bus=null;this.paths={sfx,music};this.samples=new Map();this.music=new MusicPlayer(this);this.musicEnabled=true;}
 attach(context){if(this.context===context)return;this.context=context;this.bus=context.createGain();this.bus.gain.value=this.muted?0:1;this.bus.connect(context.destination);this.music.attach(context,this.bus);this.loadSamples();}
 setMuted(value){this.muted=!!value;if(this.bus)this.bus.gain.setTargetAtTime(this.muted?0:1,this.context.currentTime,.025);if(this.muted)this.silence();}
 setMusicEnabled(on){this.musicEnabled=!!on;this.music.setEnabled(on);}
 async loadSamples(){if(this.sampleLoad||typeof fetch!=='function'||!this.context)return;this.sampleLoad=(async()=>{try{const manifest=await fetch(this.paths.sfx+'manifest.json').then(r=>r.ok?r.json():null);if(!manifest)return;await Promise.all(Object.entries(manifest.cues).map(async([cue,files])=>{const buffers=(await Promise.all(files.map(f=>fetch(this.paths.sfx+f).then(r=>r.arrayBuffer()).then(d=>new Promise((ok,no)=>this.context.decodeAudioData(d,ok,no))).catch(()=>null)))).filter(Boolean);if(buffers.length)this.samples.set(cue,buffers);}));}catch{}})();return this.sampleLoad;}
 play(kind='place',variant=0){const c=this.context;if(this.muted||!c||c.state==='suspended'||this.voices>=16)return false;const now=c.currentTime;if(now-(this.last.get(kind)??-1)<(GAP[kind]??.055))return false;this.last.set(kind,now);
  const buffers=this.samples.get(kind);if(buffers){const s=c.createBufferSource(),g=c.createGain();s.buffer=buffers[(variant+Math.floor(Math.random()*buffers.length))%buffers.length];s.playbackRate.value=kind==='step'?.92+Math.random()*.16:.97+Math.random()*.06;g.gain.value=(VOLUME[kind]??.5)*(this.reading?.3:1);s.connect(g).connect(this.bus);this.voices++;s.onended=()=>{s.disconnect();g.disconnect();this.voices--;};s.start(now);return true;}
  const [a,b,duration,volume]=CUES[kind]||CUES.place,o=c.createOscillator(),g=c.createGain();o.type=['step','impact','land','place'].includes(kind)?'triangle':'sine';const pitch=kind==='step'?1+(variant%3)*.18:1;o.frequency.setValueAtTime(a*pitch,now);o.frequency.exponentialRampToValueAtTime(b*pitch,now+duration);g.gain.setValueAtTime(.0001,now);g.gain.linearRampToValueAtTime(volume*(this.reading?.25:1),now+.008);g.gain.exponentialRampToValueAtTime(.0001,now+duration);o.connect(g).connect(this.bus);this.voices++;o.onended=()=>{o.disconnect();g.disconnect();this.voices--;};o.start(now);o.stop(now+duration+.02);return true;}
 ambience(active,area=0){const c=this.context;if(!c)return;if(!this.wind&&active&&c.state==='running'){const source=c.createBufferSource(),buffer=c.createBuffer(1,c.sampleRate*2,c.sampleRate),data=buffer.getChannelData(0);let n=41;for(let i=0;i<data.length;i++){n=(Math.imul(n,1664525)+1013904223)>>>0;data[i]=(n/4294967296*2-1)*.35;}source.buffer=buffer;source.loop=true;const filter=c.createBiquadFilter(),gain=c.createGain();filter.type='lowpass';filter.frequency.value=360;gain.gain.value=0;source.connect(filter).connect(gain).connect(this.bus);source.start();this.wind={source,filter,gain};}if(this.wind){this.wind.filter.frequency.setTargetAtTime([340,600,430][area]||340,c.currentTime,.4);this.wind.gain.gain.setTargetAtTime(active?(this.reading?.002:.008):0,c.currentTime,.12);}}
 frame({position,height=1,moving=false,grounded=true,stage='ground',area=0,active=false,scene=null,intensity=0,footfallSerial=null,partner=null}={}){this.ambience(active,area);this.music.update(scene,intensity,this.reading);if(!position)return;const old=this.lastPosition;this.lastPosition={x:position.x,z:position.z};if(active&&old&&moving&&grounded){const d=Math.hypot(position.x-old.x,position.z-old.z);if(d<.5){this.distance+=d;if(partner==='slytherin'){if(this.distance>.45){this.play('rustle',area);this.distance=0;}}else if(!Number.isFinite(footfallSerial)&&this.distance>.30+height*.19){this.play('step',area);this.distance=0;}}}else this.distance=0;if(Number.isFinite(footfallSerial)){if(active&&moving&&grounded&&this.lastFootfall!==undefined&&footfallSerial>this.lastFootfall)this.play('step',area);this.lastFootfall=footfallSerial;}if(active&&stage==='landing'&&this.stage==='air')this.play('land',area);if(active&&stage==='anticipation'&&this.stage==='ground')this.play('jump');this.stage=stage;}
 silence(){this.ambience(false);}
}

// Arena music: each track has a base stem and an optional action stem of the same length. Segments are
// scheduled back to back with their reverb tails overlapping, so loops stay seamless even with MP3 padding.
export const MUSIC_SCENES=['whisperwood','skyreach','stormglass'];
export class MusicPlayer{
 constructor(audio){this.audio=audio;this.context=null;this.manifest=null;this.buffers=new Map();this.current=null;this.wanted=null;this.enabled=true;this.intensity=0;this.bufferLimit=4;}
 attach(context,destination){this.context=context;this.out=context.createGain();this.out.gain.value=.42;this.out.connect(destination);}
 setEnabled(on){this.enabled=!!on;if(!on)this.stop();}
 async load(){if(this.manifest!==null)return this.manifest;this.loading??=fetch(this.audio.paths.music+'manifest.json').then(r=>r.ok?r.json():false).catch(()=>false);this.manifest=await this.loading;if(!this.manifest){this.manifest=null;this.loading=null;}return this.manifest;}
 buffer(file){if(this.buffers.has(file)){const hit=this.buffers.get(file);this.buffers.delete(file);this.buffers.set(file,hit);return hit;}if(!this.buffers.has(file)){const p=fetch(this.audio.paths.music+file).then(r=>{if(!r.ok)throw Error('music missing');return r.arrayBuffer();}).then(d=>new Promise((ok,no)=>this.context.decodeAudioData(d,ok,no)));this.buffers.set(file,p);p.catch(()=>{if(this.buffers.get(file)===p)this.buffers.delete(file);});while(this.buffers.size>this.bufferLimit)this.buffers.delete(this.buffers.keys().next().value);}return this.buffers.get(file);}
 // Called every frame: switches scene with a crossfade, keeps segments scheduled and follows intensity.
 update(scene,intensity=0,ducked=false){const c=this.context;if(!c||c.state!=='running'||this.audio.muted||!this.enabled){if(this.current&&(this.audio.muted||!this.enabled))this.stop();return;}
  if(scene!==this.wanted){this.wanted=scene;this.switchTo(scene);}
  const t=this.current;if(!t||!t.started)return;const now=c.currentTime;
  for(const stem of t.stems){while(stem.next<now+1.5){this.segment(stem,stem.next);stem.next+=t.loop;}}
  this.intensity+=(intensity-this.intensity)*.04;const action=t.stems.find(s=>s.name==='action');if(action)action.gain.gain.setTargetAtTime(this.intensity*.85,now,.4);
  this.out.gain.setTargetAtTime(ducked?.13:.42,now,.25);
 }
 segment(stem,at){const s=this.context.createBufferSource();s.buffer=stem.buffer;s.connect(stem.gain);s.start(Math.max(at,this.context.currentTime));stem.sources.push(s);s.onended=()=>{s.disconnect();stem.sources=stem.sources.filter(x=>x!==s);};}
 async switchTo(scene){const old=this.current;this.current=null;if(old)this.fadeOut(old);if(!scene)return;const manifest=await this.load();const info=manifest?.tracks?.[scene];if(!info||this.wanted!==scene)return;
  try{const names=['base','action'].filter(k=>info[k]),buffers=await Promise.all(names.map(k=>this.buffer(info[k])));if(this.wanted!==scene||this.current)return;const c=this.context,start=c.currentTime+.1,track={scene,loop:info.loop,started:true,stems:names.map((name,i)=>{const gain=c.createGain();gain.gain.value=0;gain.connect(this.out);if(name==='base'){gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(1,start+2);}return{name,buffer:buffers[i],gain,next:start,sources:[]};})};this.current=track;}catch{}}
 fadeOut(track){const c=this.context,now=c.currentTime;for(const stem of track.stems){stem.gain.gain.cancelScheduledValues(now);stem.gain.gain.setValueAtTime(stem.gain.gain.value,now);stem.gain.gain.linearRampToValueAtTime(0,now+1.6);setTimeout(()=>{for(const s of stem.sources)try{s.stop();}catch{}stem.gain.disconnect();},1800);}}
 stop(){if(this.current)this.fadeOut(this.current);this.current=null;this.wanted=null;}
}
